import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_gn_lrelu_add_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void fused_gn_lrelu_add_kernel(
    const float* input,
    const float* gamma,
    const float* beta,
    float* output,
    int batch_size,
    int hidden_size,
    int num_groups,
    float eps,
    float negative_slope
) {
    int group_size = hidden_size / num_groups;
    int batch_group_idx = blockIdx.x;
    int batch_idx = batch_group_idx / num_groups;
    int group_idx = batch_group_idx % num_groups;

    if (batch_idx >= batch_size) return;

    int group_start = group_idx * group_size;
    float sum = 0.0f;
    float sum_sq = 0.0f;

    for (int i = threadIdx.x; i < group_size; i += blockDim.x) {
        int idx = batch_idx * hidden_size + group_start + i;
        float val = input[idx];
        sum += val;
        sum_sq += val * val;
    }

    __shared__ float shared_sum[256];
    __shared__ float shared_sum_sq[256];
    __shared__ float mean, inv_std;

    int tid = threadIdx.x;
    shared_sum[tid] = sum;
    shared_sum_sq[tid] = sum_sq;
    __syncthreads();

    for (int s = blockDim.x/2; s>0; s>>=1) {
        if (tid < s) {
            shared_sum[tid] += shared_sum[tid + s];
            shared_sum_sq[tid] += shared_sum_sq[tid + s];
        }
        __syncthreads();
    }

    if (tid == 0) {
        mean = shared_sum[0] / group_size;
        float variance = (shared_sum_sq[0]/group_size) - (mean*mean);
        inv_std = rsqrtf(variance + eps);
    }
    __syncthreads();

    for (int i = tid; i < group_size; i += blockDim.x) {
        int idx = batch_idx * hidden_size + group_start + i;
        float val = input[idx];
        float normalized = (val - mean) * inv_std;
        float scaled = normalized * gamma[group_start + i] + beta[group_start + i];
        float lrelu = fmaxf(scaled, scaled * negative_slope);
        output[idx] = lrelu * 2.0f;
    }
}

torch::Tensor fused_gn_lrelu_add_cuda(
    torch::Tensor input,
    torch::Tensor gamma,
    torch::Tensor beta,
    int num_groups,
    float eps,
    float negative_slope
) {
    int batch_size = input.size(0);
    int hidden_size = input.size(1);
    auto output = torch::empty_like(input);

    int num_blocks = batch_size * num_groups;
    dim3 grid(num_blocks);
    dim3 block(256);

    fused_gn_lrelu_add_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        hidden_size,
        num_groups,
        eps,
        negative_slope
    );

    return output;
}
"""

fused_gn_lrelu_add_cpp = """
torch::Tensor fused_gn_lrelu_add_cuda(
    torch::Tensor input,
    torch::Tensor gamma,
    torch::Tensor beta,
    int num_groups,
    float eps,
    float negative_slope
);
"""

fused_gn_lrelu_add = load_inline(
    name='fused_gn_lrelu_add',
    cpp_sources=fused_gn_lrelu_add_cpp,
    cuda_sources=fused_gn_lrelu_add_source,
    functions=['fused_gn_lrelu_add_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, input_size, hidden_size, num_groups, eps=1e-5, negative_slope=0.01):
        super(ModelNew, self).__init__()
        self.fc = nn.Linear(input_size, hidden_size)
        self.num_groups = num_groups
        self.eps = eps
        self.negative_slope = negative_slope
        self.register_parameter('gamma', nn.Parameter(torch.ones(hidden_size)))
        self.register_parameter('beta', nn.Parameter(torch.zeros(hidden_size)))

    def forward(self, x):
        x = self.fc(x)
        x = fused_gn_lrelu_add.fused_gn_lrelu_add_cuda(
            x,
            self.gamma,
            self.beta,
            self.num_groups,
            self.eps,
            self.negative_slope
        )
        return x
